mapper.select:
select seq, writerid, title, content, readcount, wdate
from board
where seq=#{seq}

mapper.update:
update board
set readcount = readcount + 1
where seq=#{seq}

mapper.select:
select seq, writerid, title, content, readcount, ispinned, wdate
from notice
where seq=#{seq}

mapper.update:
update notice
set readcount = readcount + 1
where seq=#{seq}

mapper.select:
select seq, writerid, title, content, readcount, issecret, status, replycontent, replydate, wdate
from qna
where seq=#{seq}

mapper.update:
update qna
set readcount = readcount + 1
where seq=#{seq}
